create temporary view user_info_${grass_region_without_quote} as
select
    user_id
    ,sum(if(scenario_tag = '__ALL__',omni_click_cnt,0)) as item_click_cnt_30d
    ,size(collect_set(if(scenario_tag = '__ALL__' and imp_cnt>0, local_date, null))) as active_days_30d
    ,sum(if(scenario_tag = '__ALL__',order_cnt,0)) as order_30d
    ,sum(if(scenario_tag = '__ALL__',gmv,0)) as gmv_30d
    ,nvl(sum(if(scenario_tag = '__ALL__',gmv,0))/sum(if(scenario_tag='__ALL__',order_cnt,0)), 0) as backet_size
    ,sum(if(scenario_tag = 'DA_Daily Discover', click_cnt, null)) as dd_click_cnt_30d
    ,sum(if(scenario_tag = 'DA_Daily Discover', omni_click_cnt, 0)) as dd_omni_click_cnt_30d
    ,size(collect_set(if(imp_cnt>0 and scenario_tag = 'DA_Daily Discover', local_date, null))) as dd_active_days_30d
    ,sum(if(scenario_tag = 'DA_Daily Discover', order_cnt, 0)) as dd_order_30d
    ,sum(if(scenario_tag = 'DA_Daily Discover', gmv, 0)) as dd_gmv_30d
    ,nvl(sum(if(scenario_tag = 'DA_Daily Discover', gmv, 0))/sum(if(scenario_tag='DA_Daily Discover',order_cnt,0)), 0) as dd_backet_size
    ,sum(if(scenario_tag = 'DA_You May Also Like', omni_click_cnt, 0)) as ymal_omni_click_cnt_30d
    ,size(collect_set(if(imp_cnt>0 and scenario_tag = 'DA_You May Also Like', local_date, null))) as ymal_active_days_30d
    ,sum(if(scenario_tag = 'DA_You May Also Like', order_cnt, 0)) as ymal_order_30d
    ,sum(if(scenario_tag = 'DA_You May Also Like', gmv, 0)) as ymal_gmv_30d
    ,nvl(sum(if(scenario_tag = 'DA_You May Also Like', gmv, 0))/sum(if(scenario_tag = 'DA_You May Also Like', order_cnt, 0)), 0) as ymal_backet_size
    ,sum(if(scenario_tag = 'DA_Search', omni_click_cnt, 0)) as search_omni_click_cnt_30d
    ,size(collect_set(if(imp_cnt>0 and scenario_tag = 'DA_Search', local_date, null))) as search_active_days_30d
    ,sum(if(scenario_tag = 'DA_Search', order_cnt, 0)) as search_order_30d
    ,sum(if(scenario_tag = 'DA_Search', gmv, 0)) as search_gmv_30d
    ,nvl(sum(if(scenario_tag = 'DA_Search', gmv, 0))/sum(if(scenario_tag = 'DA_Search', order_cnt, 0)), 0) as search_backet_size
    ,nvl(sum(if(scenario_tag = 'DA_Daily Discover' and local_date between date_sub(${local_date}, 13) and ${local_date} and  feature_detail in ('home-daily_discover-item','home-daily_discover-item_feed_card'),imp_cnt,0 )),0) as dd_item_imp_cnt_14d
from srdi_mart.dws_sr_data_warehouse_platform_user_level_benchmark_1d
where grass_region = ${grass_region}
    and local_date between date_sub(${local_date}, 29) and ${local_date}
    and user_id > 0
    and( feature_detail = '__ALL__' and scenario_tag = '__ALL__'
        or feature_detail like 'home-daily_discover-%' and scenario_tag = 'DA_Daily Discover'
        or feature_detail like 'product-you_may_also_like-%' and scenario_tag = 'DA_You May Also Like'
        or feature_detail = '__ALL__' and scenario_tag = 'DA_Search'
        or (feature_detail in ('home-daily_discover-item','home-daily_discover-item_feed_card') and scenario_tag = 'DA_Daily Discover')
    )
group by user_id

