create temporary view user_level_platform_app_version_${grass_region_without_quote} as
select
    user_id
    ,platform
    ,app_version
    ,substring_index(app_version, '.', 2) as app_version_prefix
    ,log_timestamp
from
   (
       select
           user_id
           ,platform
           ,app_version
           ,log_timestamp
           ,row_number() over (
               partition by user_id
               order by log_timestamp desc
           ) as rn
       from srdi_mart.dwd_sr_data_warehouse_platform
       where
           grass_region = ${grass_region}
           and local_date = ${local_date}
           and operation in ('click','impression','view')
           and user_id > 0
   )
where rn = 1

