insert overwrite table ${schema}.dim_sr_data_warehouse_user_label
partition(grass_region=${grass_region}, local_date=${local_date})
select
    user.user_id
    ,user.gender
    ,user.age
    ,user.is_new_user
    ,nvl(info.item_click_cnt_30d, 0) as item_click_cnt_30d
    ,case
        when info.item_click_cnt_30d >= 150 then '150+'
        when info.item_click_cnt_30d >= 40  then '40-149'
        when info.item_click_cnt_30d >= 6   then '6-39'
        else '0-5'
    end as item_click_level
    ,nvl(info.active_days_30d, 0) as active_days_30d
    ,case
        when info.active_days_30d >= 26 then '26-30'
        when info.active_days_30d >= 16 then '16-25'
        when info.active_days_30d >= 8 then '8-15'
        when info.active_days_30d >= 1 then '1-7'
        else '0'
    end as active_level
    ,nvl(info.dd_click_cnt_30d, 0) as dd_click_cnt_30d
    ,case
        when info.dd_click_cnt_30d >= 24 then '24+'
        when info.dd_click_cnt_30d >= 8 then '8-23'
        when info.dd_click_cnt_30d >= 3 then '3-7'
        else '0-2'
    end as dd_click_level
    ,nvl(info.dd_active_days_30d, 0) as dd_active_days_30d
    ,case
        when info.dd_active_days_30d >= 26 then '26-30'
        when info.dd_active_days_30d >= 16 then '16-25'
        when info.dd_active_days_30d >= 8 then '8-15'
        when info.dd_active_days_30d >= 1 then '1-7'
        else '0'
    end as dd_active_level
    ,nvl(info.order_30d, 0) as order_30d
    ,case
        when info.order_30d >= 11 then '11+'
        when info.order_30d >= 7 then '7-10'
        when info.order_30d >= 4 then '4-6'
        when info.order_30d >= 1 then '1-3'
        else '0'
    end as order_level
    ,nvl(info.gmv_30d, 0) as gmv_cnt
    ,nvl(buyer.total_order, 0) as total_order
    ,case
        when buyer.total_order >= 5 then 'mature'
        when buyer.total_order >= 1 then 'early'
        else 'new'
    end as life_cycle
    ,nvl(income.income_level, '') as income_level
    ,nvl(info.backet_size, 0) as backet_size
    ,case
        when info.backet_size > 4.5 then '(4.5, +)'
        when info.backet_size > 0.8 then '(0.8, 4.5]'
        when info.backet_size >0 then '(0, 0.8]'
        else '0'
    end as backet_level
    ,nvl(info.dd_omni_click_cnt_30d, 0) as dd_omni_click_cnt_30d
    ,nvl(info.dd_order_30d, 0) as dd_order_30d
    ,nvl(info.dd_gmv_30d, 0) as dd_gmv_30d
    ,nvl(info.dd_backet_size, 0) as dd_backet_size
    ,nvl(info.ymal_omni_click_cnt_30d, 0) as ymal_omni_click_cnt_30d
    ,nvl(info.ymal_active_days_30d, 0) as ymal_active_days_30d
    ,nvl(info.ymal_order_30d, 0) as ymal_order_30d
    ,nvl(info.ymal_gmv_30d, 0) as ymal_gmv_30d
    ,nvl(info.ymal_backet_size, 0) as ymal_backet_size
    ,nvl(info.search_omni_click_cnt_30d, 0) as search_omni_click_cnt_30d
    ,nvl(info.search_active_days_30d, 0) as search_active_days_30d
    ,nvl(info.search_order_30d, 0) as search_order_30d
    ,nvl(info.search_gmv_30d, 0) as search_gmv_30d
    ,nvl(info.search_backet_size, 0) as search_backet_size
    ,nvl(info.dd_item_imp_cnt_14d,0) as dd_item_imp_cnt_14d
    ,version.platform
    ,version.app_version
    ,version.app_version_prefix
    ,user_purchase_type.user_purchase_type
    ,abs.order_180d
    ,abs.gmv_180d
    ,case
        when abs.abs_180d is null then 0
        when abs.abs_180d <= abs_pct.abs_pct_array[0] then 1
        when abs.abs_180d <= abs_pct.abs_pct_array[1] then 2
        when abs.abs_180d <= abs_pct.abs_pct_array[2] then 3
        when abs.abs_180d <= abs_pct.abs_pct_array[3] then 4
        else 5
    end as abs_tier_180d
    ,platform_gmv_180d_pct_category
    ,search_gmv_180d_pct_category
    ,platform_duration_180d_pct_category
    ,search_duration_180d_pct_category
from
    user_${grass_region_without_quote} user
left join
    user_info_${grass_region_without_quote} info
on user.user_id = info.user_id

left join
    buyer_info_${grass_region_without_quote} buyer
on user.user_id = buyer.user_id

left join
    income_info_${grass_region_without_quote} income
on user.user_id = income.user_id

left join
    user_level_platform_app_version_${grass_region_without_quote} version
on user.user_id = version.user_id
left join
    user_purchase_type_${grass_region_without_quote} as user_purchase_type
on user.user_id = user_purchase_type.user_id
left join
    user_abs_180d_${grass_region_without_quote} abs
on user.user_id = abs.user_id
left join
    abs_pct_${grass_region_without_quote} abs_pct
on abs.abs_180d is not null
LEFT JOIN
    user_platform_and_search_gmv_pct_category_${grass_region_without_quote} gmv_pct
ON
    user.user_id = gmv_pct.user_id
LEFT JOIN
    user_platform_and_search_duration_pct_category_${grass_region_without_quote} gmv_dur
ON
    user.user_id = gmv_dur.user_id;
